SELECT Month, Actual_Amount, Variance_Amount 
FROM fpaa_dataset.Budget_Variance_Detail 
WHERE Subtype = 'Payroll';

SELECT SUM(Actual_Amount) 
FROM fpaa_dataset.Budget_Variance_Detail 
WHERE Subtype = 'Utilities';

SELECT unit_price 
FROM fpaa_dataset.POS 
WHERE product_sku LIKE '%Apple Pie%' LIMIT 1;
